class Solution {
    private int[] w;
    private Random rand = new Random();

    public Solution(int n, int[] blacklist) {
        Set<Integer> b = new HashSet<>();
        for (int x : blacklist) b.add(x);
        w = new int[n - blacklist.length];
        int i = 0;
        for (int x = 0; x < n; ++x)
            if (!b.contains(x)) w[i++] = x;
    }

    public int pick() {
        return w[rand.nextInt(w.length)];
    }
}

