import random
class Solution:
    def __init__(self, n: int, blacklist: List[int]):
        m = n - len(blacklist)
        bl = sorted(x for x in blacklist if x < m)
        bs = set(blacklist)
        self.m = m
        self.map = {}
        j = m
        for x in bl:
            while j in bs:
                j += 1
            self.map[x] = j
            j += 1

    def pick(self) -> int:
        r = random.randrange(self.m)
        return self.map.get(r, r)

