class Solution {
    long long m;
    unordered_map<int,int> mp;
public:
    Solution(int n, vector<int>& blacklist) {
        m = n - (long long)blacklist.size();
        unordered_set<int> bs(blacklist.begin(), blacklist.end());
        vector<int> bl;
        for (int x : blacklist) if (x < m) bl.push_back(x);
        sort(bl.begin(), bl.end());
        long long j = m;
        for (int x : bl) {
            while (bs.count(j)) j++;
            mp[x] = j;
            j++;
        }
    }

    int pick() {
        int r = rand() % m;
        auto it = mp.find(r);
        return it == mp.end() ? r : it->second;
    }
};

