var Solution = function(n, blacklist) {
    this.m = n - blacklist.length;
    const bs = new Set(blacklist);
    const bl = blacklist.filter(x => x < this.m).sort((a, b) => a - b);
    this.map = new Map();
    let j = this.m;
    for (const x of bl) {
        while (bs.has(j)) j++;
        this.map.set(x, j++);
    }
};

Solution.prototype.pick = function() {
    const r = Math.floor(Math.random() * this.m);
    return this.map.has(r) ? this.map.get(r) : r;
};
